import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Solve the vertex graph coloring problem using a hybrid approach combining:
    - Degeneracy ordering for tight upper bound and initial solution
    - DSATUR heuristic with saturation degree and degree tie-breaking for refinement
    - Kempe chain local search for color class reduction
    - Iterative improvement with restarts to escape local minima

    The algorithm guarantees a valid coloring and strives for minimality within
    the 50ms execution budget for N ≤ 100.
    """
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for nb in adj[i]:
                if 0 <= nb < n:
                    neighbors[i].add(nb)

    # Remove self-loops if any
    for i in range(n):
        neighbors[i].discard(i)

    # Trivial cases
    if n == 1:
        return [0]
    if not any(len(neighbors[i]) > 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # Helper: validate coloring
    def is_valid(coloring):
        if len(coloring) != n:
            return False
        for i in range(n):
            ci = coloring[i]
            if ci < 0:
                return False
            for nb in neighbors[i]:
                if coloring[nb] == ci:
                    return False
        return True

    # Lower bound: maximum clique size via greedy approximation
    def greedy_clique():
        vertices = list(range(n))
        vertices.sort(key=lambda x: len(neighbors[x]), reverse=True)
        clique = []
        for v in vertices:
            if all((u in neighbors[v] or v in neighbors[u]) for u in clique):
                clique.append(v)
        return len(clique)

    lb = max(1, greedy_clique())

    # Upper bound: Welsh-Powell (degree ordering) - fast and reliable
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    color_wp = [-1] * n
    for v in order_wp:
        used = [False] * (n + 1)
        for u in neighbors[v]:
            if color_wp[u] != -1:
                used[color_wp[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color_wp[v] = c
    ub = max(color_wp) + 1 if n > 0 else 0

    if lb == ub:
        return color_wp

    # Compute degeneracy ordering for a tight initial upper bound
    def degeneracy_ordering():
        # Compute core numbers using greedy peeling
        degrees = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)

        # Peeling process
        order = []
        current_deg = 0
        # Copy degrees to avoid modifying original
        deg_copy = degrees[:]
        pos = [0] * n  # position of each vertex in its bucket
        for v in range(n):
            pos[v] = len(buckets[deg_copy[v]]) - 1

        for _ in range(n):
            # Find first non-empty bucket
            while current_deg <= max_deg and not buckets[current_deg]:
                current_deg += 1
            if current_deg > max_deg:
                break  # Should not happen

            # Remove vertex from bucket
            v = buckets[current_deg].pop()
            order.append(v)

            # Update neighbors
            for u in neighbors[v]:
                if deg_copy[u] > current_deg:  # Only if u not yet removed
                    # Remove u from its current bucket
                    bucket_idx = deg_copy[u]
                    buckets[bucket_idx].pop(pos[u])
                    # Decrease degree
                    deg_copy[u] -= 1
                    # Add to new bucket
                    new_bucket = deg_copy[u]
                    buckets[new_bucket].append(u)
                    pos[u] = len(buckets[new_bucket]) - 1

        return order  # This is smallest-last ordering

    # Get degeneracy ordering and color in reverse (largest-first)
    order = degeneracy_ordering()
    # Color in reverse order (from last peeled to first)
    color_degen = [-1] * n
    for v in reversed(order):
        used = [False] * (n + 1)
        for u in neighbors[v]:
            if color_degen[u] != -1:
                used[color_degen[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color_degen[v] = c
    ub_degen = max(color_degen) + 1 if n > 0 else 0
    ub = min(ub, ub_degen)  # Use the tighter upper bound

    # If lower bound equals updated upper bound, return
    if lb == ub:
        return color_degen

    # Try DSATUR with restarts and Kempe refinement
    best_coloring = color_degen[:]
    best_colors = ub

    # We'll try to improve from the degeneracy coloring
    for attempt in range(50):  # Number of restarts
        # Try DSATUR with current upper bound as limit
        color = dsatur_core(neighbors, n, best_colors, attempt)
        if color is not None and is_valid(color):
            # Apply Kempe chain refinement to reduce colors
            refined = kempe_reduce(color, neighbors, n)
            if refined is not None and is_valid(refined):
                refined_colors = len(set(refined))
                if refined_colors < best_colors:
                    best_coloring = refined
                    best_colors = refined_colors
                    # If we've reached the lower bound, we can't do better
                    if best_colors == lb:
                        return best_coloring

    # If we didn't improve, try to refine the best we have
    refined_best = kempe_reduce(best_coloring, neighbors, n)
    if refined_best is not None and is_valid(refined_best):
        refined_colors = len(set(refined_best))
        if refined_colors < best_colors:
            return refined_best

    return best_coloring

def dsatur_core(neighbors, n, k_limit, seed):
    """
    DSATUR coloring with at most k_limit colors.
    Uses saturation degree and degree in uncolored subgraph for tie-breaking.
    """
    if k_limit <= 0:
        return None
    random.seed(seed)
    color = [-1] * n
    saturation = [0] * n
    neighbor_colors = [set() for _ in range(n)]
    uncolored = set(range(n))

    while uncolored:
        # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
        v = -1
        max_sat = -1
        max_deg = -1
        for u in uncolored:
            sat_u = saturation[u]
            deg_u = sum(1 for nb in neighbors[u] if nb in uncolored)
            # Primary: saturation, secondary: degree in uncolored, tertiary: random
            if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
               (sat_u == max_sat and deg_u == max_deg and v == -1):
                if v == -1 or random.random() < 0.5:
                    v = u
                    max_sat = sat_u
                    max_deg = deg_u

        if v == -1:
            break  # Should not happen

        # Find smallest available color (First-Fit)
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
            if c >= k_limit:  # Exceeded color limit
                return None
        if c >= k_limit:
            return None
        color[v] = c
        uncolored.remove(v)

        # Update saturation and neighbor_colors for neighbors
        for u in neighbors[v]:
            if u in uncolored:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1

    return color

def kempe_reduce(color, neighbors, n):
    """
    Apply Kempe chain swaps to eliminate color classes.
    Iteratively tries to recolor vertices from the highest color class down.
    """
    if n == 0:
        return color

    color = color[:]  # Work on a copy
    # Maintain neighbor_colors for efficiency
    neighbor_colors = [set() for _ in range(n)]
    for i in range(n):
        for nb in neighbors[i]:
            if color[nb] != -1:
                neighbor_colors[i].add(color[nb])

    colors_used = set(color)
    if not colors_used:
        return color
    max_color = max(colors_used)
    k = max_color + 1

    # Try to eliminate color classes from highest to lowest
    for target_color in range(k - 1, 0, -1):
        # Get vertices with target_color
        target_vertices = [v for v in range(n) if color[v] == target_color]
        if not target_vertices:
            continue  # This color class is already empty

        made_progress = False
        # Try to recolor each vertex in this class
        for v in target_vertices:
            # Try direct recoloring to a lower color
            for c in range(target_color):
                if c not in neighbor_colors[v]:
                    # Direct move: recolor v to c
                    # Update neighbor_colors: remove target_color, add c
                    for u in neighbors[v]:
                        neighbor_colors[u].discard(target_color)
                        neighbor_colors[u].add(c)
                    color[v] = c
                    made_progress = True
                    break
            if made_progress:
                break

            # Try Kempe chain swap
            for c in range(target_color):
                # Get the Kempe chain component of v in colors {target_color, c}
                visited = set()
                stack = [v]
                component = set()
                count_target = 0
                count_c = 0
                while stack:
                    u = stack.pop()
                    if u in visited:
                        continue
                    visited.add(u)
                    col_u = color[u]
                    if col_u == target_color:
                        count_target += 1
                        component.add(u)
                    elif col_u == c:
                        count_c += 1
                        component.add(u)
                    # Explore neighbors with colors target_color or c
                    for nb in neighbors[u]:
                        if nb not in visited:
                            col_nb = color[nb]
                            if col_nb == target_color or col_nb == c:
                                stack.append(nb)

                # Swapping reduces target_color count if count_target > count_c
                if count_target > count_c:
                    # Perform swap: target_color <-> c in the component
                    for u in component:
                        if color[u] == target_color:
                            color[u] = c
                        elif color[u] == c:
                            color[u] = target_color
                    # Update neighbor_colors for all vertices affected
                    for u in component:
                        # Recompute neighbor_colors[u] from scratch
                        neighbor_colors[u] = set()
                        for nb in neighbors[u]:
                            if color[nb] != -1:
                                neighbor_colors[u].add(color[nb])
                    color[v] = c  # v is now color c
                    made_progress = True
                    break
            if made_progress:
                break

        if made_progress:
            # After change, restart the color class elimination from the highest
            return kempe_reduce(color, neighbors, n)

    return color

