def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj
        if n > 0 and not isinstance(graph[0], list):
            graph = [[x] if not isinstance(x, list) else x for x in graph]

    if n == 0:
        return []
    if all(len(neighbors) == 0 for neighbors in graph):
        return [0] * n

    # Precompute degrees for efficiency
    degree = [len(graph[i]) for i in range(n)]

    def greedy_first_fit(order):
        coloring = [-1] * n
        for v in order:
            used = [False] * n
            for nb in graph[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    def smallest_last_ordering():
        # Smallest-last ordering (Matula & Beck)
        remaining = set(range(n))
        order = []
        deg = [len(graph[v]) for v in range(n)]
        for _ in range(n):
            min_deg = float('inf')
            min_v = -1
            for v in remaining:
                d = 0
                for nb in graph[v]:
                    if nb in remaining:
                        d += 1
                if d < min_deg:
                    min_deg = d
                    min_v = v
            if min_v == -1:
                break
            order.append(min_v)
            remaining.remove(min_v)
        return order[::-1]

