                        if degree[v] > max_orig_deg:
                            max_orig_deg = degree[v]
                            final_candidates = [v]
                        elif degree[v] == max_orig_deg:
                            final_candidates.append(v)
                    v = random.choice(final_candidates) if final_candidates else random.choice(deg_candidates)

            used_colors = saturation[v]
            c = 0
            while c in used_colors:
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            for nb in graph[v]:
                if nb in uncolored:
                    saturation[nb].add(c)

        return coloring

    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            v = max(uncolored, key=lambda x: sum(1 for nb in graph[x] if nb in uncolored))
            independent_set = {v}
            U = uncolored - {v}
            W = set()
            for nb in graph[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)

            while U:
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
