                        saturation[nb].add(color)
            color += 1

        return coloring

    def kempe_chains(coloring):
        current = coloring[:]
        n_local = n
        improved = True
        while improved:
            improved = False
            max_color = max(current) if n_local > 0 else -1
            if max_color <= 0:
                break
            for target_color in range(max_color, 0, -1):
                vertices_target = [v for v in range(n_local) if current[v] == target_color]
